 "content": "from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    foreground = max((v for v in counts if v != background), key=lambda v: counts[v])
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == foreground]
    r0, r1 = min(r for r, _ in points), max(r for r, _ in points)
    c0, c1 = min(c for _, c in points), max(c for _, c in points)
    out = [row[:] for row in grid]
    for r in range(r0, r1 + 1):
        for c in range(c0, c1 + 1):
            if r in (r0, r1) or c in (c0, c1):
                if out[r][c] == background:
                    out[r][c] = 2
    return out

